          ssize_t n = pread_retry (fd, header_buffer, H_READ_SIZE,
                                   *start_offset + H_START);
          if (n < 0)
            return DWFL_E_ERRNO;
          if (n < H_READ_SIZE)
            return DWFL_E_BADELF;

          header = header_buffer - H_START;
        }

