      uint32_t magic2;
      uint16_t version;
      memcpy (&magic1, header + H_MAGIC1, sizeof (uint16_t));
      memcpy (&magic2, header + H_MAGIC2, sizeof (uint32_t));
      memcpy (&version, header + H_VERSION, sizeof (uint16_t));
